use mip_codex::{mps,heuristic::Repair,objective_repair,solve::Result};
use std::time::{Instant,Duration};
fn main(){let a:Vec<_>=std::env::args().collect();if a.get(1).is_some_and(|v|v=="build-info"){println!("{}",serde_json::json!({"source_directory":env!("CARGO_MANIFEST_DIR"),"source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT,"library_source_directory":mip_codex::BUILD_SOURCE_DIRECTORY,"library_source_fingerprint":mip_codex::BUILD_SOURCE_FINGERPRINT}));return;}let m=mps::read(&a[1]).unwrap();let seed:serde_json::Value=serde_json::from_slice(&std::fs::read(&a[2]).unwrap()).unwrap();let values=seed["values"].as_object().unwrap();let x:Vec<_>=m.variables.iter().map(|v|values.get(&v.name).and_then(|x|x.as_f64()).unwrap_or(0.)).collect();let repair=Repair::new(&m);assert!(repair.candidate_check(&x));let lo:Vec<_>=m.variables.iter().map(|v|v.lower).collect();let hi:Vec<_>=m.variables.iter().map(|v|v.upper).collect();let seconds:f64=a[3].parse().unwrap();assert!(seconds>0.&&seconds<=30.);let start=Instant::now();let initial=start+Duration::from_secs_f64(seconds.min(0.5));let extension=(seconds>0.5).then(||start+Duration::from_secs_f64(seconds));let (x,stats)=objective_repair::improve_budgeted(&m,&repair,&x,&lo,&hi,initial,extension).unwrap();let r=Result{status:"feasible_unit_objective_budget_diagnostic".into(),objective:Some(m.objective(&x)),values:Some(m.variables.iter().zip(&x).map(|(v,&x)|(v.name.clone(),x)).collect()),seconds:start.elapsed().as_secs_f64(),..Result::default()};serde_json::to_writer(std::fs::File::create(&a[4]).unwrap(),&r).unwrap();println!("{}",serde_json::json!({"objective":r.objective,"stats":stats,"seconds":r.seconds}));}
